WITH clientes_ativos AS (
    SELECT id_cliente, nome FROM clientes WHERE status = 'ATIVO'
),
faturamento AS (
    SELECT id_cliente, SUM(receita) AS total FROM vendas GROUP BY id_cliente
)
SELECT c.nome, f.total
FROM clientes_ativos AS c
JOIN faturamento AS f USING (id_cliente);

