CREATE OR REPLACE TEMP VIEW v_qualidade_usuarios AS
SELECT *, CASE WHEN email IS NULL THEN 1 ELSE 0 END AS flag_sem_email
FROM usuarios;

SELECT * FROM v_qualidade_usuarios WHERE flag_sem_email = 1;

intermediario.solucao:
CREATE OR REPLACE TEMP VIEW v_qualidade_usuarios AS
SELECT *, CASE WHEN email IS NULL THEN 1 ELSE 0 END AS flag_sem_email FROM usuarios;

CREATE OR REPLACE TEMP VIEW v_resumo_qualidade AS
SELECT COUNT(*) AS total,
       SUM(flag_sem_email) AS sem_email,
       ROUND(100 * AVG(flag_sem_email), 1) AS pct_sem_email
FROM v_qualidade_usuarios;

SELECT * FROM v_resumo_qualidade;

