basico.solucao:
SELECT f.id_venda, d.uf
FROM fato_vendas AS f
LEFT JOIN dim_loja AS d ON f.loja_id = d.loja_id;

intermediario.solucao:
-- Errado: SP aparece com 200
SELECT d.uf, SUM(f.valor) FROM fato_vendas f JOIN dim_loja d USING (loja_id) GROUP BY d.uf;

-- Correto (Databricks: QUALIFY row_number() ... = 1; aqui com subconsulta portável)
WITH dim_atual AS (
    SELECT * FROM (
        SELECT *, row_number() OVER (PARTITION BY loja_id ORDER BY atualizado_em DESC, versao DESC) AS rn
        FROM dim_loja
    ) WHERE rn = 1
)
SELECT d.uf, SUM(f.valor) AS receita
FROM fato_vendas AS f
JOIN dim_atual AS d USING (loja_id)
GROUP BY d.uf;

