avancado.solucao:
WITH saldo AS (
    SELECT *, SUM(valor) OVER (
        PARTITION BY conta_id ORDER BY data_movimento, movimento_id
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS saldo_acumulado
    FROM movimentos
)
SELECT *,
       ROUND(100 * try_divide(valor, lag(saldo_acumulado) OVER (PARTITION BY conta_id ORDER BY data_movimento, movimento_id)), 2) AS variacao_pct
FROM saldo;

